local RegressionNewRewardAniRoot = Class('RegressionNewRewardAniRoot')
local GridCellPath = "Game.Activity.RegressionActivity.Cell.RegressionNewRewardAniRootCell"
local UIRaycastBlocker = CS.Engine.UI.UIRaycastBlocker.Instance

local JumpType = {
	One = 1,
	Five = 2,
}

local EventType = {
	GetItem = 1,
	Jump = 2,
}

local DOTween = CS.DG.Tweening.DOTween

function RegressionNewRewardAniRoot:__init()
	self.gridEnv = {}
	self.curPos = 1
end

function RegressionNewRewardAniRoot:__delete()
	self.gridEnv = nil
end

function RegressionNewRewardAniRoot:Awake()

end

function RegressionNewRewardAniRoot:RefreshGridShow(data, groupId)
	self.data = data
	self.curPos = self.data.nowStep
	self:InitGridVos(groupId)
	self:InitGridShow()
	self:RefreshStartPos(self.curPos)
end

function RegressionNewRewardAniRoot:InitGridShow()
	local count = #self.gridVos
	for i = 1, count do
		local grid = self["JumpNode"..i]
		if grid then
			local env = CfUtils.GetLuaScr(grid, GridCellPath)
			if isNotNull(env) then
				env:RefreshGridShow(self.gridVos[i], i)
				table.insert(self.gridEnv, env)
			end
		end
	end
end

function RegressionNewRewardAniRoot:RefreshStartPos(pos)
	local node = self["JumpNode"..pos]
	if node then
		self.RoleSpine.transform.localPosition = node.transform.localPosition
	end
	local env = self.gridEnv[pos]
	if isNotNull(env) then
		env:SetRewardState(false)
	end
end

function RegressionNewRewardAniRoot:StartJump(jumpType, point, buffPoints, cb)
	local jumpNum = jumpType == JumpType.One and 1 or 5
	self:StartJumpOne(jumpNum, point, buffPoints, cb)
end

function RegressionNewRewardAniRoot:GoToPos(pos)
	local lastPos = self.curPos
	self.gridEnv[self.curPos]:SetRewardState(true)
	self.curPos = pos
	self:RefreshStartPos(self.curPos)
	self:SetFlip(lastPos, self.curPos)
end

function RegressionNewRewardAniRoot:StartJumpFive()
	CfUtils.PlaySpine(self.RoleSpine, "jump", false)
end

function RegressionNewRewardAniRoot:StartJumpOne(jumpNum ,points ,buffPoints ,cb)
	UIRaycastBlocker:AddCondition("RegressionNewRewardAniRoot")
	local sequence         = DOTween.Sequence()
	for j = 1, jumpNum do
		local pos = points[tostring(j)]
		sequence:AppendCallback(function()
			CfUtils.PlayAnimation(self.Dice,"RegressionNewRewardDialog_Dice_Go")
		end)
		sequence:AppendInterval(0.16)
		sequence:AppendCallback(function()
			CfUtils.SetUISwitchImage(self.ImgIcon, pos)
		end)
		sequence:AppendInterval(1)
		sequence:AppendCallback(function()
			CfUtils.PlaySpine(self.RoleSpine, "idol", true)
		end)

		self:StartSignJump(pos, sequence)
		
		local type = buffPoints[tostring(j)].type
		if type > 0 then
			sequence:AppendCallback(function() self:ShowPopUpTxt(type,buffPoints[tostring(j)].num) end)
			sequence:AppendInterval(0.2)
		end
		
		local buffPos = buffPoints[tostring(j)].num
		if type == EventType.Jump and buffPos > 0 then
			self:StartSignJump(buffPos ,sequence)
		end
		sequence:AppendCallback(function()
			CfUtils.PlaySpine(self.RoleSpine, "reward", true)
		end)
	end
	sequence:AppendInterval(0.6)
	sequence:AppendCallback(function()
		if cb then cb() end
		CfUtils.PlaySpine(self.RoleSpine, "idol", true)
		UIRaycastBlocker:RemoveCondition("RegressionNewRewardAniRoot")
	end)
	sequence:PlayForward()
end

function RegressionNewRewardAniRoot:StartSignJump(pos,sequence)
	for i = 1, pos do
		local lastGrid = self.gridEnv[self.curPos]
		self.curPos = self.curPos + 1
		if self.curPos > #self.gridVos then
			self.curPos = 1
		end
		local grid = self.gridEnv[self.curPos]
		local position = grid.controller.transform.position
		local isNeedFlip = grid.controller.transform.localPosition.x < lastGrid.controller.transform.localPosition.x
		sequence:AppendCallback(function()
			grid:PlayEffect(false)
			CfUtils.PlaySpine(self.RoleSpine, "jump", false, isNeedFlip)
			CfUtils.SetSpineFlip(self.RoleSpine, isNeedFlip)
		end)
		sequence:Append(self.RoleSpine.transform:DOMove(position, 0.3))
		sequence:AppendCallback(function()
			grid:PlayJumpEffect()
			lastGrid:SetRewardState(true)
			grid:SetRewardState(false)
			CfUtils.PlaySpine(self.RoleSpine, "idol", true)
			grid:PlayEffect(true)
		end)
	end
end

function RegressionNewRewardAniRoot:ShowPopUpTxt(type, num)
	local txt = ""
	if type == EventType.GetItem then
		txt = localize("幸运事件：获得_num_个骰子",{_num_ = num})
	elseif type == EventType.Jump then
		txt = localize("幸运事件：前进_num_格",{_num_ = num})
	end
	GameUtils.Toast(txt)
end

function RegressionNewRewardAniRoot:SetFlip(lastPos, curPos)
	local curGrid = self.gridEnv[lastPos]
	local grid = self.gridEnv[curPos]
	local isNeedFlip = grid.controller.transform.localPosition.x < curGrid.controller.transform.localPosition.x
	CfUtils.SetSpineFlip(self.RoleSpine, isNeedFlip)
end

function RegressionNewRewardAniRoot:InitGridVos(groupId)
	local allVos = CfUtils.GetCf(AutoIds.IdSetting6509,"RegressionJackPotVo",true)
	local data = {}
	for i, v in pairs(allVos) do
		if v.group == groupId then
			table.insert(data,v)
		end
	end
	self.gridVos = data
end

function RegressionNewRewardAniRoot:OnDestroy()
	self.controller = nil--luabehaviour 中CSharp对象
	self:Delete()
end

return RegressionNewRewardAniRoot